"""Models for the iki/core plugin, generated by `iki plugin build` from its manifests.

Don't edit this file: change the manifests, then run `iki plugin makemigrations`.
"""

# ruff: noqa
# fmt: off
import datetime

from django.contrib.postgres.fields import ArrayField
from django.contrib.postgres.indexes import GinIndex
